// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 minSumVal, uint256 depositAmt, uint256 collectAmt) public {
        // Bound inputs to reasonable ranges to prevent overflows
        minSumVal = bound(minSumVal, 0, 1e24);
        depositAmt = bound(depositAmt, 0, 1e24);
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Set MinSum
        c.SetMinSum(minSumVal);
        // Initialize the contract (prevent further SetMinSum calls)
        c.Initialized();

        // Fund the contract to allow deposits
        address(c).call{value: depositAmt}("");

        // Attempt collect
        (bool collectSuccess,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // The rule: MinSum should equal the originally set value (not zero)
        assertTrue(c.MinSum() == minSumVal);
    }
}

